export type Mode = 'light' | 'dark'

export const theme = { accent: '#3b82f6' }

/** Follows the system setting until the person picks one. */
export function initialMode(): Mode {
  const saved = localStorage.getItem('mode')
  if (saved === 'light' || saved === 'dark') return saved
  return matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
}

export function setMode(mode: Mode) {
  document.documentElement.dataset.mode = mode
  localStorage.setItem('mode', mode)
}

import { useState } from 'react'
import { initialMode, setMode, type Mode } from '../theme'

export function ModeToggle() {
  const [mode, set] = useState<Mode>(initialMode)
  const flip = () => {
    const next = mode === 'dark' ? 'light' : 'dark'
    setMode(next)
    set(next)
  }
  return <button onClick={flip} aria-label="Toggle dark mode">{mode === 'dark' ? '☀︎' : '☾'}</button>
}

import { randomUUID } from 'node:crypto'

export async function createOrder(req: { items: string[] }, newId: () => string = randomUUID) {
  return { id: newId(), items: req.items }
}
